def wildcard_match(text, pattern):
    t = p = 0                    # the next character of the text and of the pattern
    star = -1                    # where the most recent "*" is in the pattern
    resume = 0                   # where in the text that star's match currently ends
    while t < len(text):
        if p < len(pattern) and pattern[p] == "*":
            star, resume = p, t              # first try: the star matches nothing
            p += 1
        elif p < len(pattern) and (pattern[p] == "?" or pattern[p] == text[t]):
            t += 1
            p += 1
        elif star != -1:
            resume += 1                      # mismatch: the last star swallows one more character, then retry
            t, p = resume, star + 1
        else:
            return False
    while p < len(pattern) and pattern[p] == "*":
        p += 1                               # once the text is used up, only stars may remain
    return p == len(pattern)
